#[test]
fn error_codes_and_accessors() {
    for code in ErrorCode::ALL {
        let parsed: ErrorCode = code.as_str().parse().unwrap();
        assert_eq!(parsed, code);
        assert_eq!(code.to_string(), code.as_str());
        assert!(!code.reason().is_empty());
        let err = Error::new(code, "m");
        assert_eq!(err.code(), code);
        assert!(err.is(code));
        assert_eq!(err.is_retryable(), code.default_retryable());
        assert_eq!(err.to_string(), "m");
    }
    assert_eq!(
        "NOPE".parse::<ErrorCode>().unwrap_err().code(),
        ErrorCode::Validation
    );
    assert_eq!(ErrorCode::from_http_status(200), None);
    assert_eq!(ErrorCode::from_http_status(302), None);
    assert_eq!(Error::from_status(204, "x").code(), ErrorCode::Unavailable);

    let io = std::io::Error::other("disk");
    let err = Error::unavailable("op: failed")
        .with_status(503)
        .with_request_id("r-1")
        .with_retryable(false)
        .with_retry_after(Duration::from_secs(2))
        .with_source(io);
    assert_eq!(err.http_status(), Some(503));
    assert_eq!(err.request_id(), Some("r-1"));
    assert!(!err.is_retryable());
    assert_eq!(err.retry_after(), Some(Duration::from_secs(2)));
    assert_eq!(err.cause().unwrap().to_string(), "disk");
    assert_eq!(std::error::Error::source(&err).unwrap().to_string(), "disk");
    assert!(format!("{err:?}").contains("disk"));
    let renamed = err.clone().with_message("other");
    assert_eq!(renamed.message(), "other");
    for (err, code) in [
        (Error::config("c"), ErrorCode::Config),
        (Error::validation("v"), ErrorCode::Validation),
        (Error::not_found("n"), ErrorCode::NotFound),
        (Error::conflict("c"), ErrorCode::Conflict),
        (Error::timeout("t"), ErrorCode::Timeout),
        (Error::unsupported("u"), ErrorCode::Unsupported),
        (Error::cancelled("x"), ErrorCode::Cancelled),
    ] {
        assert_eq!(err.code(), code);
        assert!(std::error::Error::source(&err).is_none());
    }
    let json_err: Error = serde_json::from_str::<serde_json::Value>("{")
        .unwrap_err()
        .into();
    assert_eq!(json_err.code(), ErrorCode::Validation);
    assert!(json_err.message().contains("unexpected end of input"));
    let json_err: Error = serde_json::from_str::<serde_json::Value>("{x")
        .unwrap_err()
        .into();
    assert!(json_err.message().contains("syntax"));
    let json_err: Error = serde_json::from_str::<u8>("\"s\"").unwrap_err().into();
    assert!(json_err.message().contains("unexpected data"));
    struct Failing;
    impl std::io::Write for Failing {
        fn write(&mut self, _: &[u8]) -> std::io::Result<usize> {
            Err(std::io::Error::other("no"))
        }
        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }
    let json_err: Error = serde_json::to_writer(Failing, &1).unwrap_err().into();
    assert!(json_err.message().contains("I/O"));
}

#[test]
fn secret_type() {
    let s = Secret::new("hunter2-secret");
    assert_eq!(format!("{s:?}"), REDACTED);
    assert_eq!(format!("{s}"), REDACTED);
    assert_eq!(serde_json::to_string(&s).unwrap(), "\"[REDACTED]\"");
    assert_eq!(s.expose_secret(), "hunter2-secret");
    assert_eq!(s.reveal(), "hunter2-secret");
    assert!(!s.is_empty());
    assert!(Secret::default().is_empty());
    assert_eq!(Secret::from("a"), Secret::from("a".to_owned()));
    assert_ne!(Secret::from("a"), Secret::from("b"));
    assert_ne!(Secret::from("a"), Secret::from("ab"));
}

#[test]
fn redaction_helpers() {
    for h in [
        "Authorization",
        "proxy-authorization",
        "Cookie",
        "set-cookie",
        "X-Api-Key",
        "x-auth-token",
        "X-Session-Id",
        "x-signature",
        "x-credential",
        "x-goog-apikey",
    ] {
        assert!(is_sensitive_header(h), "{h}");
    }
    for h in ["content-type", "accept", "user-agent", "x-request-id"] {
        assert!(!is_sensitive_header(h), "{h}");
    }
    assert!(is_sensitive_field("DB_PASSWORD"));
    assert!(is_sensitive_field("client_secret"));
    assert!(!is_sensitive_field("username"));
    let h = redact_headers([("Authorization", "Bearer x"), ("Accept", "json")]);
    assert_eq!(h["authorization"], REDACTED);
    assert_eq!(h["accept"], "json");

    let u = redact_url("https://user:pw@host/p?token=abc&page=2#frag");
    assert!(!u.contains("pw@") && !u.contains("abc"), "{u}");
    assert!(u.contains("page=2"));
    assert_eq!(redact_url("https://host/p"), "https://host/p");
    assert_eq!(redact_url("not a url?token=abc"), "not a url");

    let v = json!({"user": "u", "password": "p", "nested": {"api_key": "k", "list": [{"token": "t"}, 1]}, "custom_field": "c"});
    let r = redact_fields(&v, &["CUSTOM"]);
    assert_eq!(r["user"], "u");
    assert_eq!(r["password"], REDACTED);
    assert_eq!(r["nested"]["api_key"], REDACTED);
    assert_eq!(r["nested"]["list"][0]["token"], REDACTED);
    assert_eq!(r["nested"]["list"][1], 1);
    assert_eq!(r["custom_field"], REDACTED);

    assert_eq!(
        redact_text("a hunter22 b hunter2 c", &["hunter2", "hunter22", "abc"]),
        "a [REDACTED] b [REDACTED] c"
    );
    assert_eq!(redact_text("short abc", &["abc"]), "short abc");
    assert_eq!(redact_text("none", &Vec::<String>::new()), "none");
    assert_eq!(truncate("abcdef", 3), "abc…");
    assert_eq!(truncate("abc", 3), "abc");
}

#[test]
fn retry_policy() {
    let p = RetryPolicy::default();
    assert_eq!(p.max_retries, 3);
    assert_eq!(p.initial_backoff, Duration::from_millis(100));
    assert_eq!(p.max_backoff, Duration::from_secs(10));
    assert_eq!(p.multiplier, 2.0);
    assert_eq!(p.max_retry_after, Duration::from_secs(60));
    assert_eq!(p.backoff_cap(0), Duration::from_millis(100));
    assert_eq!(p.backoff_cap(3), Duration::from_millis(800));
    assert_eq!(p.backoff_cap(10), Duration::from_secs(10));
    assert_eq!(p.backoff_cap(u32::MAX), Duration::from_secs(10));
    for n in 0..8 {
        assert!(p.backoff(n) <= p.backoff_cap(n));
    }
    let fixed = p.clone().with_random(RandomSource::fixed(0.25));
    assert_eq!(fixed.backoff(1), Duration::from_millis(50));
    assert_eq!(RandomSource::fixed(f64::NAN).next(), 0.0);
    assert_eq!(RandomSource::fixed(7.0).next(), 1.0);
    assert!(format!("{:?}", RandomSource::default()).contains("RandomSource"));
    assert_eq!(RetryPolicy::none().max_retries, 0);
    assert_eq!(RetryPolicy::default().with_max_retries(9).max_retries, 9);
    assert!(p.validate().is_ok());
    assert!(RetryPolicy {
        multiplier: f64::NAN,
        ..RetryPolicy::default()
    }
    .validate()
    .is_err());

    let now = SystemTime::UNIX_EPOCH + Duration::from_secs(1_000_000_000);
    assert_eq!(
        parse_retry_after("120", now),
        Some(Duration::from_secs(120))
    );
    assert_eq!(
        parse_retry_after("1.5", now),
        Some(Duration::from_millis(1500))
    );
    assert_eq!(parse_retry_after("-1.5", now), None);
    assert_eq!(parse_retry_after("", now), None);
    assert_eq!(parse_retry_after("soon", now), None);
    let later = httpdate::fmt_http_date(now + Duration::from_secs(30));
    assert_eq!(
        parse_retry_after(&later, now),
        Some(Duration::from_secs(30))
    );
    let earlier = httpdate::fmt_http_date(now - Duration::from_secs(30));
    assert_eq!(parse_retry_after(&earlier, now), Some(Duration::ZERO));
}

#[test]
fn health_status() {
    let ok = HealthStatus::healthy("ok").with_detail("k", "v");
    assert!(ok.healthy);
    assert_eq!(ok.details["k"], "v");
    let json = serde_json::to_value(&ok).unwrap();
    assert_eq!(
        json,
        json!({"healthy": true, "status": "ok", "details": {"k": "v"}})
    );
    let back: HealthStatus =
        serde_json::from_value(json!({"healthy": false, "status": "x"})).unwrap();
    assert_eq!(back.details, BTreeMap::new());
    assert_eq!(
        HealthStatus::from_error(Error::cancelled("c"))
            .unwrap_err()
            .code(),
        ErrorCode::Cancelled
    );
    assert_eq!(
        HealthStatus::from_error(Error::config("c"))
            .unwrap_err()
            .code(),
        ErrorCode::Config
    );
    let un = HealthStatus::from_error(Error::unavailable("refused")).unwrap();
    assert_eq!((un.healthy, un.status.as_str()), (false, "unreachable"));
    let st = HealthStatus::from_error(Error::from_status(500, "x")).unwrap();
    assert_eq!((st.healthy, st.status.as_str()), (false, "unhealthy"));
    assert_eq!(st.details["httpStatus"], "500");
}

#[tokio::test]
async fn poll_until_helper() {
    let calls = Arc::new(AtomicU32::new(0));
    let opts = PollOptions {
        timeout: Duration::from_secs(2),
        interval: Duration::from_millis(5),
    };
    let c = calls.clone();
    let v = poll_until("wait", opts, || {
        let c = c.clone();
        async move {
            let n = c.fetch_add(1, Ordering::SeqCst);
            match n {
                0 => Ok(None),
                1 => Err(Error::unavailable("transient")),
                _ => Ok(Some(n)),
            }
        }
    })
    .await
    .unwrap();
    assert_eq!(v, 2);
    let err = poll_until("wait", opts, || async {
        Err::<Option<()>, _>(Error::validation("bad"))
    })
    .await
    .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    let short = PollOptions {
        timeout: Duration::from_millis(30),
        interval: Duration::from_millis(10),
    };
    let err = poll_until("logs.wait", short, || async {
        Ok::<Option<()>, Error>(None)
    })
    .await
    .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Timeout);
    assert!(err
        .message()
        .starts_with("logs.wait: condition not met within 30 ms"));
    assert!(std::error::Error::source(&err).is_none());
    let err = poll_until("w", short, || async {
        Err::<Option<()>, _>(Error::timeout("slow"))
    })
    .await
    .unwrap_err();
    assert_eq!(std::error::Error::source(&err).unwrap().to_string(), "slow");
    let d = PollOptions::default();
    assert_eq!(
        (d.timeout, d.interval),
        (Duration::from_secs(30), Duration::from_secs(1))
    );
}

#[tokio::test]
async fn close_group() {
    let group = CloseGroup::new();
    let count = Arc::new(AtomicU32::new(0));
    for _ in 0..2 {
        let c = count.clone();
        group.register(move || {
            Box::pin(async move {
                c.fetch_add(1, Ordering::SeqCst);
            })
        });
    }
    assert!(format!("{group:?}").contains("callbacks: 2"));
    assert!(!group.is_closed());
    group.close().await;
    group.close().await;
    assert!(group.is_closed());
    assert_eq!(count.load(Ordering::SeqCst), 2);
    // late registration runs in the background
    let c = count.clone();
    let (tx, rx) = tokio::sync::oneshot::channel();
    group.register(move || {
        Box::pin(async move {
            c.fetch_add(1, Ordering::SeqCst);
            let _ = tx.send(());
        })
    });
    rx.await.unwrap();
    assert_eq!(count.load(Ordering::SeqCst), 3);
}

#[test]
fn close_group_late_registration_without_runtime() {
    let group = CloseGroup::default();
    let rt = tokio::runtime::Builder::new_current_thread()
        .build()
        .unwrap();
    rt.block_on(group.close());
    group.register(|| Box::pin(async {}));
    assert!(group.is_closed());
}

#[test]
fn clocks() {
    let m = ManualClock::default();
    let t0 = m.now();
    m.advance(Duration::from_secs(5));
    assert_eq!(m.now() - t0, Duration::from_secs(5));
    assert!(format!("{m:?}").contains("ManualClock"));
    let s = SystemClock;
    assert!(s.now() <= SystemClock.now());
}
